def check_solution(b):
    # Equation: a^2 - a(2^(b+1) - 1) + 2 * 3^b = 0
    # Discriminant Delta = (2^(b+1) - 1)^2 - 4 * 2 * 3^b
    term_a = (2**(b+1) - 1)
    delta = term_a**2 - 8 * (3**b)

    if delta < 0:
        return None, "Negative discriminant"

    import math
    sqrt_delta = math.isqrt(delta)

    if sqrt_delta**2 == delta:
        # Integer solutions exist
        a1_num = term_a + sqrt_delta
        a2_num = term_a - sqrt_delta

        if a1_num % 2 == 0 and a2_num % 2 == 0:
            a1 = a1_num // 2
            a2 = a2_num // 2

            # Check if a are positive integers
            if a1 > 0 and a2 > 0:
                return [(a1, b), (a2, b)]
            elif a1 > 0:
                return [(a1, b)]
            elif a2 > 0:
                return [(a2, b)]

    return None, "Not a perfect square"

solutions = {}
for b in range(1, 9): # Checking b=1 up to b=8
    s = check_solution(b)
    if s:
        solutions[b] = s

print(f"Solutions found: {solutions}")

# Calculate the sum for the found solutions
total_sum = 0
for b, pairs in solutions.items():
    for a, b_val in pairs:
        total_sum += (a + b_val)

print(f"Total sum based on initial check: {total_sum}")
